                _ = &many_off;
                if (takes_many) {
                    many_off = 3;
                }
                var opt_off: usize = 0;
                _ = &opt_off;
                if (takes_one_optional) {
                    opt_off = 1;
                }
                const help_start = (((len + 1) + many_off) + opt_off);
                return ParamHelp{ .takes_value = (if (takes_many) Values.many else (if (takes_one_optional) Values.one_optional else Values.one)), .id = Help{ .msg = mem.trim(u8, line[help_start..], " \t"), .value = line[1..len] } };
            }
