            _ = self.@"arena".deinit();
    }

pub fn flag(self: @This(), comptime name: []const u8) bool {
            return self.clap.flag(name);
    }

pub fn option(self: *const @This(), comptime name: []const u8) ?[]const u8 {
            return self.clap.option(name);
    }

pub fn options(self: *const @This(), comptime name: []const u8) []const []const u8 {
            return self.clap.options(name);
    }

pub fn positionals(self: *const @This()) []const []const u8 {
            return self.clap.positionals();
    }

pub fn remaining(self: *const @This()) []const []const u8 {
            return self.clap.remaining();
    }

pub fn hasFlag(comptime name: []const u8) bool {
            return ClapType.hasFlag(name);
    }
};
}

pub fn parse(comptime Id: type, comptime params: []const Param(Id), opt: ParseOptions) !Args(Id, params) {
        const ArgsType = Args(Id, params);
        var iter = args.OsIterator.init(opt.allocator);
        _ = &iter;
        var res = ArgsType{ .@"arena" = iter.@"arena", .exe_arg = iter.exe_arg, .clap = undefined };
        _ = &res;
        const iter_ptr = (blk: {
        break :blk @as(*args.OsIterator, @ptrCast(@alignCast(@as(*anyopaque, @ptrCast(@alignCast(&(iter)))))));

});
        res.clap = try parseEx(Id, params, iter_ptr, ParseOptions{ .allocator = res.@"arena".allocator(), .diagnostic = opt.diagnostic, .stop_after_positional_at = opt.stop_after_positional_at });
        return res;
}

pub fn parseEx(comptime Id: type, comptime params: []const Param(Id), iter: anytype, opt: ParseOptions) !ComptimeClap(Id, params) {
        const Clap = ComptimeClap(Id, params);
        return try Clap.parse(iter, opt);
}

pub fn helpFull(stream: anytype, comptime Id: type, params: []const Param(Id), comptime ErrorType: type, context: anytype, helpText: anytype, valueText: anytype) !void {
        var max_spacing: usize = 0;
        _ = &max_spacing;
        var p_i: usize = 0;
        _ = &p_i;
        while ((p_i < params.len)) : (p_i = (p_i + 1)) {
            const param = params[@as(usize, @intCast(p_i))];
            var cs = io.countingWriter(io.null_writer);
            _ = &cs;
            _ = try printParam(cs.writer(), Id, param, ErrorType, context, valueText);
            const written = (if (comptime @typeInfo(@TypeOf(cs.bytes_written)) == .@"enum") cp_cast_int(usize, @intFromEnum(cs.bytes_written)) else cp_cast_int(usize, cs.bytes_written));
            if ((max_spacing < written)) {
                max_spacing = written;
            }
        }
        var i: usize = 0;
        _ = &i;
        while ((i < params.len)) : (i = (i + 1)) {
            const param = params[@as(usize, @intCast(i))];
            if (((param.names.short == null) and (param.names.long == null))) {
                continue;
            }
            const help_text = try helpText(context, param);
            if ((help_text.len > 0)) {
                var cs = io.countingWriter(stream);
                _ = &cs;
                _ = try stream.print("\t", &.{});
                _ = try printParam(cs.writer(), Id, param, ErrorType, context, valueText);
                _ = try stream.splatByteAll(32, (max_spacing - (if (comptime @typeInfo(@TypeOf(cs.bytes_written)) == .@"enum") cp_cast_int(usize, @intFromEnum(cs.bytes_written)) else cp_cast_int(usize, cs.bytes_written))));
                _ = try stream.print("\t{s}\n", .{ try helpText(context, param) });
            }
        }
}

pub fn printParam(stream: anytype, comptime Id: type, param: Param(Id), comptime _Error: type, context: anytype, valueText: anytype) !void {
        _ = &_Error;
        if (param.names.short) |s| {
            _ = &s;
            _ = try stream.print("-{c}", .{ s });
        } else {
            _ = try stream.print("  ", &.{});
        }
        if (param.names.long) |l| {
            _ = &l;
            if ((param.names.short != null)) {
                _ = try stream.print(", ", &.{});
            } else {
                _ = try stream.print("  ", &.{});
            }
            _ = try stream.print("--{s}", .{ l });
        }
        switch (param.takes_value) {
.none => {

},
.one => {
_ = try stream.print(" <{s}>", .{ try valueText(context, param) });
},
.one_optional => {
_ = try stream.print(" <{s}>?", .{ try valueText(context, param) });
},
.many => {
_ = try stream.print(" <{s}>...", .{ try valueText(context, param) });
},
}
}

pub fn ctxHelp(c: anytype, p: anytype) EmptyErr![]const u8 {
        return c.helpText(p);
}

pub fn ctxValue(c: anytype, p: anytype) EmptyErr![]const u8 {
        return c.valueText(p);
}

pub fn helpEx(stream: anytype, comptime Id: type, params: []const Param(Id), helpText: anytype, valueText: anytype) !void {
        return helpFull(stream, Id, params, EmptyErr, .{ .helpText = helpText, .valueText = valueText }, ctxHelp, ctxValue);
}

pub fn simplePrintParam(param: ParamHelp) !void {
        _ = Output.pretty("\n", &.{});
        if (param.names.short) |s| {
            _ = &s;
            if (((param.takes_value != .none) and (param.names.long == null))) {
                _ = Output.pretty("  <cyan>-{c}<r><d><cyan>=\\<val\\><r>", .{ s });
            } else {
                _ = Output.pretty("  <cyan>-{c}<r>", .{ s });
            }
        } else {
            _ = Output.pretty("    ", &.{});
        }
        if (param.names.long) |l| {
            _ = &l;
            if ((param.names.short != null)) {
                _ = Output.pretty(", ", &.{});
            } else {
                _ = Output.pretty("  ", &.{});
            }
            if ((param.takes_value != .none)) {
                _ = Output.pretty("<cyan>--{s}<r><d><cyan>=\\<val\\><r>", .{ l });
            } else {
                _ = Output.pretty("<cyan>--{s}<r>", .{ l });
            }
        } else {
            _ = Output.pretty("    ", &.{});
        }
}

pub fn paramLen(param: ParamHelp) usize {
        const flags_len: usize = (if ((param.names.long != null)) param.names.long.?.len else 0);
        var value_len: usize = 0;
        _ = &value_len;
        if ((param.takes_value != .none)) {
            value_len = 6;
        }
        return (flags_len + value_len);
}

pub fn simpleHelp(params: []const ParamHelp) void {
        var max_spacing: usize = 2;
        _ = &max_spacing;
        var p_i: usize = 0;
        _ = &p_i;
        while ((p_i < params.len)) : (p_i = (p_i + 1)) {
            const len = paramLen(params[@as(usize, @intCast(p_i))]);
            if ((max_spacing < len)) {
                max_spacing = len;
            }
        }
        var i: usize = 0;
        _ = &i;
        while ((i < params.len)) : (i = (i + 1)) {
            const param = params[@as(usize, @intCast(i))];
            if (((param.names.short == null) and (param.names.long == null))) {
                continue;
            }
            const desc_text = getHelpSimple(param);
            if ((desc_text.len == 0)) {
                continue;
            }
            const default_allocator = bun.default_allocator;
            const total_len = paramLen(param);
            const num_spaces_after = (max_spacing - total_len);
            var spaces_after = ((default_allocator.alloc(u8, num_spaces_after)) catch unreachable);
            _ = &spaces_after;
            var spaces_guard = FreeDefaultGuard(@TypeOf(spaces_after)){ .slice = spaces_after };
            _ = &spaces_guard;
            var __spaces_guard_moved = false; _ = &__spaces_guard_moved;
            defer if (!__spaces_guard_moved) { __spaces_guard_moved = true; const __T = @TypeOf(spaces_guard); if (@typeInfo(__T) == .optional) { if (spaces_guard) |__cp_opt_v| { const __OptT = @TypeOf(__cp_opt_v); if (@typeInfo(__OptT) == .pointer and @typeInfo(__OptT).pointer.size == .one and (if (@hasField(@TypeOf(@typeInfo(__OptT).pointer), "is_const")) !@typeInfo(__OptT).pointer.is_const else !@typeInfo(__OptT).pointer.attrs.@"const")) { const __CpChild = @typeInfo(__OptT).pointer.child; if (@typeInfo(__CpChild) == .@"struct" and @hasDecl(__CpChild, "__cp_deinit")) { __cp_opt_v.__cp_deinit(); } } else if (@typeInfo(__OptT) == .@"struct" and @hasDecl(__OptT, "__cp_deinit")) { var _drop_val = __cp_opt_v; _drop_val.__cp_deinit(); } } } else if (@typeInfo(__T) == .pointer and @typeInfo(__T).pointer.size == .one and (if (@hasField(@TypeOf(@typeInfo(__T).pointer), "is_const")) !@typeInfo(__T).pointer.is_const else !@typeInfo(__T).pointer.attrs.@"const")) { const __CpChild = @typeInfo(__T).pointer.child; if (@typeInfo(__CpChild) == .@"struct" and @hasDecl(__CpChild, "__cp_deinit")) { spaces_guard.__cp_deinit(); } } else if (@typeInfo(__T) == .@"struct" and @hasDecl(__T, "__cp_deinit")) { var _drop_val = spaces_guard; _drop_val.__cp_deinit(); } };
            _ = &spaces_guard;
            var s_i: usize = 0;
            _ = &s_i;
            while ((s_i < num_spaces_after)) : (s_i = (s_i + 1)) {
                spaces_after[cp_cast_int(usize, s_i)] = 32;
            }
            _ = ((simplePrintParam(param)) catch unreachable);
            _ = Output.pretty("  {s}  {s}", .{ spaces_after, desc_text });
        }
}

pub fn simpleHelpBunTopLevel(comptime params: []const ParamHelp) void {
        const max_spacing: usize = 30;
        const space_buf: []const u8 = "                              ";
        const computed_max_spacing = (comptime blk: {
        var res: usize = 2;
        _ = &res;
        var p_i: usize = 0;
        _ = &p_i;
        while ((p_i < params.len)) : (p_i = (p_i + 1)) {
            const len = paramLen(params[@as(usize, @intCast(p_i))]);
            if ((res < len)) {
                res = len;
            }
        }
        break :blk res;
});
        if ((computed_max_spacing > max_spacing)) {
            _ = @compileError("a parameter is too long to be nicely printed in `bun --help`");
        }
        comptime var idx: usize = 0;
        _ = &idx;
        inline while ((idx < params.len)) : (idx = (idx + 1)) {
            const param = params[@as(usize, @intCast(idx))];
            if ((!((param.names.short == null) and (param.names.long == null)))) {
                const desc_text = (comptime getHelpSimple(param));
                if ((desc_text.len != 0)) {
                    _ = ((simplePrintParam(param)) catch unreachable);
                    const total_len = (comptime paramLen(param));
                    const num_spaces_after = (max_spacing - total_len);
                    _ = Output.pretty(std.fmt.comptimePrint("{s}{s}", .{ space_buf[0..num_spaces_after], desc_text }), &.{});
                }
            }
        }
}

pub fn help(stream: anytype, params: []const ParamHelp) !void {
        _ = try helpEx(stream, Help, params, getHelpSimple, getValueSimple);
}

pub fn getHelpSimple(param: ParamHelp) []const u8 {
        return param.id.msg;
}

pub fn getValueSimple(param: ParamHelp) []const u8 {
        return @field(param.id, "value");
}

pub fn usageFull(stream: anytype, comptime Id: type, params: []const Param(Id), comptime _Error: type, context: anytype, valueText: anytype) !void {
        _ = &_Error;
        var cos = io.countingWriter(stream);
        _ = &cos;
        const cs = cos.writer();
        var i: usize = 0;
        _ = &i;
        while ((i < params.len)) : (i = (i + 1)) {
            const param = params[@as(usize, @intCast(i))];
            const name = ((param.names.short) orelse continue);
            if ((param.takes_value != .none)) {
                continue;
            }
            if ((cos.bytes_written == 0)) {
                _ = try stream.writeAll("[-");
            }
            _ = try cs.writeByte(name);
        }
        if ((cos.bytes_written != 0)) {
            _ = try cs.writeByte(93);
        }
        var positional: ?Param(Id) = null;
        _ = &positional;
        var j: usize = 0;
        _ = &j;
        while ((j < params.len)) : (j = (j + 1)) {
            const param = params[@as(usize, @intCast(j))];
            if (((param.takes_value == .none) and (param.names.short != null))) {
                continue;
            }
            const prefix = (if ((param.names.short != null)) "-" else "--");
            var short_buf: [1]u8 = .{ 0 };
            _ = &short_buf;
            var name: []const u8 = "";
            _ = &name;
            if (param.names.short) |s| {
                _ = &s;
                short_buf[cp_cast_int(usize, 0)] = s;
                name = short_buf[0..1];
            } else {
                if (param.names.long) |l| {
                    _ = &l;
                    name = l;
                } else {
                    positional = param;
                    continue;
                }
            }
            if ((cos.bytes_written != 0)) {
                _ = try cs.writeByte(32);
            }
            _ = try cs.print("[{s}{s}", .{ prefix, name });
            switch (param.takes_value) {
.none => {

},
.one => {
_ = try cs.print(" <{s}>", .{ try valueText(context, param) });
},
.one_optional => {
_ = try cs.print(" <{s}>?", .{ try valueText(context, param) });
},
.many => {
_ = try cs.print(" <{s}>...", .{ try valueText(context, param) });
},
}
            _ = try cs.writeByte(93);
        }
        if (positional) |p| {
            _ = &p;
            if ((cos.bytes_written != 0)) {
                _ = try cs.writeByte(32);
            }
            _ = try cs.print("<{s}>", .{ try valueText(context, p) });
        }
}

pub fn usageEx(stream: anytype, comptime Id: type, params: []const Param(Id), valueText: anytype) !void {
        return usageFull(stream, Id, params, EmptyErr, .{ .valueText = valueText }, ctxValue);
}

pub fn usage(stream: anytype, params: []const ParamHelp) !void {
        _ = try usageEx(stream, Help, params, getValueSimple);
}
